import { runEvaluation } from "@/lib/finding-extras";
import * as E from "@pac/cdp-engine";
import { admin } from "@/lib/supabase/admin";
import { computeScore } from "@/lib/scoring";
import { consultantOnAssessment } from "@/lib/staff";
import { fromDbError, json, problem } from "@/lib/problem";

export const runtime = "nodejs";

// Build the action plan from the frozen score and its stored findings (engine buildPlan), once per score version.
// Starts today. Actions are created as DRAFT, generated by the rules engine.
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const g = await consultantOnAssessment(req, id);
  if (g instanceof Response) return g;
  const db = admin();
  const { data: ev } = await db.from("evaluation").select("score_version, payload_hash").eq("assessment_id", id).order("score_version", { ascending: false }).limit(1).maybeSingle();
  if (!ev) return problem({ code: "VALIDATION_FAILED", status: 422, title: "Run findings first." });
  const { data: done } = await db.from("plan").select("score_version, payload_hash").eq("assessment_id", id).eq("score_version", ev.score_version).maybeSingle();
  if (done) return json({ ...done, created: false });

  // The engine needs Decimal objects, not stored JSON: recompute and refuse unless both hashes reproduce.
  const { data: sc } = await db.from("score_object").select("payload_hash").eq("assessment_id", id).eq("version", ev.score_version).single();
  const s = await computeScore(id, g.asm.engagement_id, sc ? [sc.payload_hash] : []);
  // An evaluation stored before the segment signals were added (October 2026) is reproduced without them, as the score is.
  let evaluation = await runEvaluation(id, g.asm.tenant_id, ev.score_version, s);
  if (E.payloadHash(E.toJsonable(evaluation)) !== ev.payload_hash) evaluation = E.evaluate(s.obj, s.setup);
  if (s.hash !== sc?.payload_hash || E.payloadHash(E.toJsonable(evaluation)) !== ev.payload_hash) {
    return problem({ code: "INTERNAL", status: 500, title: "The frozen score or findings could not be reproduced." });
  }
  const start = new Date().toISOString().slice(0, 10);
  let plan;
  try { plan = E.toJsonable(E.buildPlan(s.obj, evaluation, s.setup, start)); }
  catch (e) {
    const m = String((e as Error).message);
    if (m.startsWith("INSUFFICIENT_DATA") || m.startsWith("PLAN_INCOHERENT")) return problem({ code: "VALIDATION_FAILED", status: 422, title: m.split(": ")[1] ?? m });
    throw e;
  }
  const hash = E.payloadHash(plan);
  const { data, error } = await db.rpc("rpc_plan_store", { p_actor: g.a.userId, p_assessment: id, p_version: ev.score_version, p_start: start, p_plan: plan as never, p_hash: hash });
  if (error) return fromDbError(error.message);
  // Rules 2.2, plan built after the report was released: propose now (a no-op until a report is released, and on 2.0 and 2.1 plans).
  const proposed = await db.rpc("rpc_plan_propose", { p_assessment: id, p_version: ev.score_version });
  if (proposed.error) return fromDbError(proposed.error.message);
  return json({ score_version: ev.score_version, payload_hash: hash, ...(data as object) }, 201);
}
